  when(threads.advanceHead(anyMap())).thenAnswer(c->{if(failHead)return 0;store.head=store.head.add(BigInteger.ONE);return 1;});when(threads.advanceIssues(anyMap())).thenAnswer(c->{store.issue=store.issue.add(BigInteger.ONE);return 1;});when(threads.confirmations(anyMap())).thenAnswer(c->store.reviews.stream().filter(r->store.invalidations.stream().noneMatch(i->i.reviewId().equals(r.reviewId()))).sorted(Comparator.comparing(AnnotationThreadProtocol.Review::reviewId)).toList());
