 static final class Store{AnnotationThreadProtocol.Row origin;AnnotationAnchorProtocol.Pointer pointer;Map<String,AnnotationAnchorProtocol.Anchor>anchors=new HashMap<>();List<JsonNode>transitions=new ArrayList<>();Map<String,InterfaceProtocol.ObjectRef>artifacts=new HashMap<>();Map<String,String>events=new HashMap<>(),audits=new HashMap<>();List<AnnotationDecisionProtocol.Row> decisions=new ArrayList<>();List<AnnotationDecisionProtocol.History>replies=new ArrayList<>();List<AnnotationThreadProtocol.Review>reviews=new ArrayList<>();List<AnnotationThreadProtocol.Invalidation>invalidations=new ArrayList<>();Map<String,UploadOperationRow>operations=new HashMap<>();UploadOperationRow operation;String audit,current=NEW;BigInteger head=BigInteger.ONE,issue=BigInteger.ONE;
  Store copy(){var s=new Store();s.origin=origin;s.pointer=pointer;s.anchors.putAll(anchors);transitions.forEach(t->s.transitions.add(t.deepCopy()));s.artifacts.putAll(artifacts);s.events.putAll(events);s.audits.putAll(audits);s.decisions.addAll(decisions);s.replies.addAll(replies);s.reviews.addAll(reviews);s.invalidations.addAll(invalidations);s.operations.putAll(operations);s.operation=operation;s.audit=audit;s.current=current;s.head=head;s.issue=issue;return s;}}
